CREATE OR REPLACE VIEW DStr_VItem AS
 SELECT I.Id     AS Id         ,
        I.Num    AS Num        ,
        I.Name   AS Name       ,
        S.Id     AS Status_Id  ,
        S.Name   AS Status_Name,
        U.Id     AS Unit_Id    ,
        U.Name   AS Unit_Name  ,
        Sp1.Id   AS Spc1_Id    ,
        Sp1.Name AS Spc1_Name  ,
        Sp2.Id   AS Spc2_Id    ,
        Sp2.Name AS Spc2_Name  ,
        Sp3.Id   AS Spc3_Id    ,
        Sp3.Name AS Spc3_Name  ,
        I.Mnum   AS Mnum       ,
        I.Rem    AS Rem 
   FROM DStr_Item      I  ,
        Phs_Cod_Status S  ,
        Cpy_Cod_Unit   U  ,
        DStr_Cod_Spc1  Sp1,
        DStr_Cod_Spc2  Sp2,
        DStr_Cod_Spc3  Sp3
  WHERE I.Status_Id = S.Id
    AND I.Unit_Id   = U.Id
    AND I.Spc1_Id   = Sp1.Id
    AND I.Spc2_Id   = Sp2.Id
    AND I.Spc3_Id   = Sp3.Id;

