CREATE OR REPLACE VIEW DStr_VFDoc3 AS
 SELECT Mst_Id         AS Mst_Id        ,
        Trt_Id         AS Trt_Id        ,
        Period_Id      AS Period_Id     ,
        Period_Name    AS Period_Name   ,
        Stor_Id        AS Stor_Id       ,
        Stor_Num       AS Stor_Num      ,
        Stor_Name      AS Stor_Name     ,
        Stor_Acc_Id    AS Stor_Acc_Id   ,
        Stor_Status_Id AS Stor_Status_Id,
        Acc_Id         AS Acc_Id        ,
        Acc_Num        AS Acc_Num       ,
        Acc_Name       AS Acc_Name      ,
        Cost_Id        AS Cost_Id       ,
        Cost_Num       AS Cost_Num      ,
        Cost_Name      AS Cost_Name     ,
        Mst_Mnum       AS Mst_Mnum      ,
        Mst_Mdate      AS Mst_Mdate     ,
        Doc_Id         AS Doc_Id        ,
        Doc_Name       AS Doc_Name      ,
        Mst_Docn       AS Mst_Docn      ,
        Mst_Docd       AS Mst_Docd      ,
        Mst_Rnum       AS Mst_Rnum      ,
        Mst_Rdate      AS Mst_Rdate     ,
        Mst_Rdocn      AS Mst_Rdocn     ,
        Mst_Rdocd      AS Mst_Rdocd     ,
        Mst_Rem        AS Mst_Rem       ,
        Trn_Id         AS Trn_Id        ,
        Item_Id        AS Item_Id       ,
        Item_Num       AS Item_Num      ,
        Item_Name      AS Item_Name     ,
        Item_Status_Id AS Item_Status_Id,
        Item_Spc1_Id   AS Item_Spc1_Id  ,
        Item_Spc2_Id   AS Item_Spc2_Id  ,
        Item_Spc3_Id   AS Item_Spc3_Id  ,
        Status_Id      AS Status_Id     ,
        Trn_Qnt        AS Trn_Qnt       ,
        Trn_Qnt        AS Qnt           ,
        Trn_Price      AS Trn_Price     ,
        Trn_Amt        AS Trn_Amt       ,
        Trn_Amt        AS Amt           ,
        Trn_Cst        AS Trn_Cst       ,
        Trn_Cst        AS Cst           ,
        Trn_Qnt        AS In_Qnt        ,
        Trn_Amt        AS In_Amt        ,
        Trn_Cst        AS In_Cst        ,
        0              AS Ou_Qnt        ,
        0              AS Ou_Amt        ,
        0              AS Ou_Cst        ,
        Trn_Rem        AS Trn_Rem 
   FROM DStr_VFInDoc3 
 UNION ALL
 SELECT Mst_Id         AS Mst_Id        ,
        Trt_Id         AS Trt_Id        ,
        Period_Id      AS Period_Id     ,
        Period_Name    AS Period_Name   ,
        Stor_Id        AS Stor_Id       ,
        Stor_Num       AS Stor_Num      ,
        Stor_Name      AS Stor_Name     ,
        Stor_Acc_Id    AS Stor_Acc_Id   ,
        Stor_Status_Id AS Stor_Status_Id,
        Acc_Id         AS Acc_Id        ,
        Acc_Num        AS Acc_Num       ,
        Acc_Name       AS Acc_Name      ,
        Cost_Id        AS Cost_Id       ,
        Cost_Num       AS Cost_Num      ,
        Cost_Name      AS Cost_Name     ,
        Mst_Mnum       AS Mst_Mnum      ,
        Mst_Mdate      AS Mst_Mdate     ,
        Doc_Id         AS Doc_Id        ,
        Doc_Name       AS Doc_Name      ,
        Mst_Docn       AS Mst_Docn      ,
        Mst_Docd       AS Mst_Docd      ,
        Mst_Rnum       AS Mst_Rnum      ,
        Mst_Rdate      AS Mst_Rdate     ,
        Mst_Rdocn      AS Mst_Rdocn     ,
        Mst_Rdocd      AS Mst_Rdocd     ,
        Mst_Rem        AS Mst_Rem       ,
        Trn_Id         AS Trn_Id        ,
        Item_Id        AS Item_Id       ,
        Item_Num       AS Item_Num      ,
        Item_Name      AS Item_Name     ,
        Item_Status_Id AS Item_Status_Id,
        Item_Spc1_Id   AS Item_Spc1_Id  ,
        Item_Spc2_Id   AS Item_Spc2_Id  ,
        Item_Spc3_Id   AS Item_Spc3_Id  ,
        Status_Id      AS Status_Id     ,
        -1 * Trn_Qnt   AS Trn_Qnt       ,
        -1 * Trn_Qnt   AS Qnt           ,
        Trn_Price      AS Trn_Price     ,
        -1 * Trn_Amt   AS Trn_Amt       ,
        -1 * Trn_Amt   AS Amt           ,
        -1 * Trn_Cst   AS Trn_Cst       ,
        -1 * Trn_Cst   AS Cst           ,
        0              AS In_Qnt        ,
        0              AS In_Amt        ,
        0              AS In_Cst        ,
        Trn_Qnt        AS Ou_Qnt        ,
        Trn_Amt        AS Ou_Amt        ,
        Trn_Cst        AS Ou_Cst        ,
        Trn_Rem        AS Trn_Rem 
   FROM DStr_VFOuDoc3;

CREATE OR REPLACE VIEW DStr_VCompInDoc12 AS
 SELECT Trt_Id     AS Trt_Id    ,
        Period_Id  AS Period_Id ,
