        Mst_Mdate  AS Mst_Mdate ,
        Mst_Doc_Id AS Mst_Doc_Id,
        Mst_Docn   AS Mst_Docn  ,
        Mst_Docd   AS Mst_Docd  ,
        Item_Id    AS Item_Id   ,
        Trn_Qnt    AS Trn_Qnt1  ,
        0          AS Trn_Qnt2 
   FROM DStr_VInDoc1                     
 UNION ALL
 SELECT Trt_Id     AS Trt_Id    ,
        Period_Id  AS Period_Id ,
        Stor_Id    AS Stor_Id   ,
        Acc_Id     AS Acc_Id    ,
        Cost_Id    AS Cost_Id   ,
