        Mst_Doc_Id AS Mst_Doc_Id,
        Mst_Docn   AS Mst_Docn  ,
        Mst_Docd   AS Mst_Docd  ,
        Item_Id    AS Item_Id   ,
        0          AS Trn_Qnt1  ,
        Trn_Qnt    AS Trn_Qnt2 
   FROM DStr_VInDoc2;

